import {badge,button,conditionTabs,emptyState,errorSummary,escapeHtml as esc,field,icon,money,notice,offerCard,pagination,productImage,profitOf,updatesNotice} from '../components/ui.js';
import {categories,initialOffers,initialSettings,alertExamples} from './data.js';
import {comparablesFor,filteredOffers,PAGE_SIZE,scenarios} from './model.js';

export const viewNames={offers:'Seu garimpo',interests:'Interesses',alerts:'Alertas',settings:'Configurações',system:'Design system',setup:'Primeiro uso',reference:'Referência de preço'};
export const variants=['editorial','compact','night'];
const variantNames={editorial:'Editorial',compact:'Comparação',night:'Mesa de análise'};
export const titleBlock=(title,text,action='')=>`<div class="page-heading"><div><h1 tabindex="-1">${esc(title)}</h1><p>${esc(text)}</p></div>${action}</div>`;

export function shell(state,content) {
  const nav=(view,label,name)=>`<a class="nav-link ${state.view===view?'is-active':''}" href="?view=${view}" data-nav="${view}" ${state.view===view?'aria-current="page"':''}>${icon(name)}<span>${label}</span>${view==='alerts'?`<span class="nav-count">${state.alerts.length}</span>`:''}</a>`;
  return `<aside class="sidebar ${state.menu?'is-open':''}" id="main-navigation"><a class="brand" href="?view=offers" data-nav="offers"><span class="brand-mark">${icon('compass')}</span><span>garimpei<span class="brand-period">.</span></span></a><span class="prototype-tag">Protótipo navegável</span><nav aria-label="Navegação principal">${nav('offers','Seu garimpo','compass')}${nav('interests','Interesses','sliders')}${nav('alerts','Alertas','bell')}<div class="nav-divider"></div>${nav('settings','Configurações','settings')}${nav('system','Design system','grid')}</nav><div class="sidebar-bottom"><span class="status-label"><i aria-hidden="true"></i> Exemplo local</span><p>Explore as jornadas com dados de demonstração.</p><a class="sidebar-help" href="../README.md">Sobre este protótipo ${icon('external')}</a></div></aside>
  <div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="${state.menu?'Fechar':'Abrir'} navegação" aria-controls="main-navigation" aria-expanded="${state.menu}">${icon(state.menu?'close':'list')}</button><span class="breadcrumb">Garimpei <span>/</span> <strong>${state.offer?'Detalhes da oferta':viewNames[state.view]}</strong></span><div class="topbar-right"><span class="local-location">${icon('pin')} São Paulo, SP</span><span class="demo-indicator">Dados fictícios</span><span class="avatar" aria-hidden="true">G</span></div></header><main id="main" class="content" tabindex="-1">${content}<footer class="page-footer"><span>Garimpei. Compare antes de decidir.</span><span>Protótipo · sem coleta ou envio real</span></footer></main></div>`;
}

export function offersView(state) {
  if(!state.setup.complete)return titleBlock('Seu próximo garimpo começa aqui.','Configure sua região, seus custos e os produtos que quer acompanhar.')+emptyState({title:'Vamos preparar seu garimpo',text:'A primeira coleta só começa quando você concluir a configuração.',action:button({label:'Configurar meu garimpo',attributes:'data-nav="setup"',iconName:'plus'})});
  return titleBlock('Um bom negócio começa no detalhe.','Compare ofertas, confira os custos e encontre seu próximo garimpo.',button({label:'Editar interesses',variant:'secondary',iconName:'sliders',attributes:'data-nav="interests"'}))+
  `<div class="monitor-strip"><span>${icon('refresh')} ${['stale','stopped'].includes(state.scenario)?'Última coleta no exemplo: 08/11, 10:42':'Última coleta no exemplo: 10/11, 10:42'}</span><a class="text-link" href="?view=interests" data-nav="interests">${state.products.length} produtos e ${state.selectedCategories.length} categorias ${icon('right')}</a></div>
  <p class="sr-only" id="offer-count" aria-live="polite"></p>${conditionTabs(state.condition,state.offers)}<div class="filter-bar"><label class="search-field">${icon('search')}<span class="sr-only">Buscar ofertas</span><input id="offer-search" type="search" placeholder="Busque por produto ou modelo" value="${esc(state.search)}"></label><label class="filter-select"><span class="sr-only">Filtrar modalidade</span><select id="delivery-filter"><option value="all" ${state.delivery==='all'?'selected':''}>Todas as modalidades</option><option value="pickup" ${state.delivery==='pickup'?'selected':''}>Retirada em São Paulo</option><option value="shipping" ${state.delivery==='shipping'?'selected':''}>Com envio</option></select></label><span class="sort-label">${icon('sliders')} Maior lucro estimado</span></div>
  <div class="category-row" role="group" aria-label="Filtrar categoria">${['Todas',...categories].map(category=>`<button class="category-chip ${state.category===category?'is-active':''}" aria-pressed="${state.category===category}" data-category="${esc(category)}">${esc(category)}</button>`).join('')}</div><div id="update-region" aria-live="polite">${state.pendingUpdates.length?updatesNotice(state.pendingUpdates.length):''}</div><div id="offer-results" role="tabpanel" aria-labelledby="tab-${state.condition}">${resultsView(state)}</div>`;
}

function operationNotice(scenario) {
  const statuses={
    error:['A coleta não foi atualizada','Não foi possível acessar a fonte no exemplo. As ofertas da última coleta disponível foram preservadas.'],
    stopped:['O acompanhamento está interrompido','Verifique se os processos do Garimpei estão em execução. Os dados abaixo são da última coleta bem-sucedida.'],
    stale:['Os dados podem estar desatualizados','Confira o horário da última coleta e o anúncio original antes de decidir. Não há confirmação de preço ou disponibilidade atual.'],
    partial:['A coleta foi concluída parcialmente','Uma das buscas não foi concluída. A cobertura está incompleta e os últimos dados conhecidos foram preservados.']
  };
  const item=statuses[scenario];
  return item?notice({title:item[0],text:item[1],kind:'warning'}):'';
}

export function resultsView(state) {
  let banner=operationNotice(state.scenario);
  if(state.condition==='defect')banner+=notice({title:'Defeitos, reparo ou peças',text:'Estas ofertas não geram alertas pelo WhatsApp. O custo de reparo não foi estimado.',kind:'warning'});
  if(state.condition==='unknown')banner+=notice({title:'O funcionamento ainda não foi confirmado',text:'Confira o anúncio e classifique a oferta nos detalhes. Enquanto estiver nesta aba, ela não gera alertas.',kind:'info'});
  if(state.scenario==='unavailable')return notice({title:'Não foi possível carregar as ofertas',text:'A consulta está indisponível neste exemplo. Isso não significa que não existam anúncios.',kind:'danger',action:button({label:'Tentar novamente',variant:'secondary',attributes:'data-action="retry"'})});
  if(['loading','initial'].includes(state.scenario))return `${banner}${state.scenario==='initial'?notice({title:'Primeira coleta em andamento',text:'Estamos organizando os anúncios iniciais. Esta coleta é silenciosa e não gera alertas.',kind:'info'}):''}<p class="results-summary" role="status">Carregando ofertas de demonstração…</p><div class="offer-grid" aria-busy="true">${Array.from({length:3},()=>'<div class="offer-card" aria-hidden="true"><div class="skeleton skeleton-image"></div><div class="skeleton skeleton-line"></div><div class="skeleton skeleton-line short"></div></div>').join('')}</div>`;
  const all=state.scenario==='empty'?[]:filteredOffers(state);
  if(!all.length) {
    const filtered=!!state.search||state.category!=='Todas'||state.delivery!=='all';
    return banner+emptyState({title:filtered?'Nenhuma oferta com esses filtros':'Nenhuma oferta encontrada nesta coleta',text:filtered?'Tente outro nome ou remova os filtros para ver as ofertas disponíveis.':'A coleta terminou sem resultados para esta seleção. Você pode revisar seus interesses; não é uma falha de consulta.',action:button({label:filtered?'Limpar filtros':'Revisar interesses',attributes:filtered?'data-action="clear-filters"':'data-nav="interests"'})});
  }
  state.page=Math.min(state.page,Math.ceil(all.length/PAGE_SIZE));
  const items=all.slice((state.page-1)*PAGE_SIZE,state.page*PAGE_SIZE);
  const common={rate:state.settings.rate,shipping:state.settings.shipping*100};
  const summary=`<div class="results-summary"><span><strong>${all.length}</strong> ofertas para explorar</span><span>Preços e imagens de demonstração</span></div>`;
  let content;
  if(state.variant==='compact')content=`<div class="comparison-wrap"><table class="comparison"><caption class="sr-only">Ofertas por lucro; sem estimativa ao final</caption><thead><tr><th scope="col">Produto</th><th scope="col">Compra</th><th scope="col">Revenda estimada</th><th scope="col">Lucro estimado</th><th scope="col">Modalidade</th><th scope="col"><span class="sr-only">Detalhes</span></th></tr></thead><tbody>${items.map(offer=>{const profit=profitOf(offer,common.rate,common.shipping);return `<tr><td><a class="table-product" href="?offer=${offer.id}" data-offer="${offer.id}">${offer.image?`<img src="assets/${offer.image}" alt="" width="56" height="56">`:icon('grid')}<span><strong>${esc(offer.title)}</strong><small>${esc(offer.category)} · ${esc(offer.age)}</small></span></a></td><td>${money(offer.price)}</td><td>${money(offer.resale)}</td><td class="${profit===null?'muted':profit<0?'negative':'positive'}">${profit===null?'Estimativa indisponível':money(profit)}</td><td>${offer.delivery==='pickup'?'Retirada':offer.delivery==='shipping'?'Envio':'Não confirmada'}</td><td><a class="icon-button" href="?offer=${offer.id}" data-offer="${offer.id}" aria-label="Ver detalhes de ${esc(offer.title)}">${icon('right')}</a></td></tr>`;}).join('')}</tbody></table></div>`;
  else if(state.variant==='night') {
    const selected=items.find(offer=>offer.id===state.selectedReview)||items[0];
    content=`<div class="analysis-layout"><div class="analysis-list">${items.map(offer=>`<button class="analysis-item ${offer.id===selected.id?'is-selected':''}" data-review="${offer.id}" aria-pressed="${offer.id===selected.id}">${offer.image?`<img src="assets/${offer.image}" alt="" width="64" height="64">`:icon('grid')}<span><strong>${esc(offer.title)}</strong><small>${money(offer.price)} · ${esc(offer.age)}</small></span><b>${profitOf(offer,common.rate,common.shipping)===null?'Sem estimativa':money(profitOf(offer,common.rate,common.shipping))}</b></button>`).join('')}</div><div class="analysis-preview">${offerCard(selected,common)}</div></div>`;
  } else content=offerCard(items[0],{...common,feature:true})+(items.length>1?`<div class="section-heading"><h2>Continue o garimpo</h2><span>${items.length-1} nesta página</span></div><div class="offer-grid">${items.slice(1).map(offer=>offerCard(offer,common)).join('')}</div>`:'');
  return banner+summary+content+pagination(state.page,all.length,PAGE_SIZE);
}

export function detailView(state) {
  const offer=state.offers.find(item=>item.id===state.offer);
  if(!offer)return titleBlock('Oferta não encontrada','Escolha uma oferta de demonstração para consultar os detalhes.')+button({label:'Voltar ao garimpo',attributes:'data-nav="offers"'});
  const profit=profitOf(offer,state.settings.rate,state.settings.shipping*100);
  const freight=offer.delivery==='unknown'?null:offer.delivery==='pickup'?0:offer.freight??state.settings.shipping*100;
  const fee=Number.isFinite(offer.resale)?Math.round(offer.resale*state.settings.rate/100):null;
  const condition={good:['Funcionamento informado','positive'],defect:['Defeito informado','danger'],unknown:['Condição não confirmada','warning']}[offer.condition];
  const refs=comparablesFor(offer);
  const action=choice=>button({label:choice==='good'?'Funciona bem':'Não funciona bem',variant:choice==='good'?'primary':'secondary',disabled:!!state.pending,attributes:`data-classify="${choice}" data-id="${offer.id}"`});
  const manual=offer.manualCondition!==null;
  return `<a class="back-link" href="?view=offers" data-nav="offers">${icon('left')} Voltar ao garimpo</a>`+titleBlock(offer.title,'Confira o anúncio, as referências e cada custo antes de decidir.')+
  `<div id="update-region" aria-live="polite">${state.pendingUpdates.some(update=>update.id===offer.id)?updatesNotice(state.pendingUpdates.length,true):''}</div><div class="detail-layout"><div>${offer.availability==='unavailable'?notice({title:'Anúncio indisponível na origem',text:'Os dados exibidos são da última consulta conhecida. Preço e disponibilidade atuais não estão confirmados.',kind:'warning'}):''}<div class="detail-image">${productImage(offer)}${offer.image?'<span class="photo-credit">Imagem ilustrativa</span>':''}</div><div class="detail-description"><div class="row">${badge(condition[0],condition[1])}${manual?badge('Classificação manual','info','check'):''}${badge(offer.delivery==='pickup'?'Retirada local':offer.delivery==='shipping'?'Com envio':'Modalidade não confirmada','neutral')}</div><h2>O que o anúncio informa</h2><p>${esc(offer.description)}</p><p class="muted small">A classificação não comprova o estado real do produto.</p><dl class="source-details"><div><dt>Origem</dt><dd>${esc(offer.origin)}</dd></div><div><dt>Identificação</dt><dd>${esc(offer.sourceId)}</dd></div><div><dt>Localização</dt><dd>${esc(offer.location||'Não informada')}</dd></div><div><dt>Identificado no exemplo</dt><dd>${esc(new Date(offer.firstSeenAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))}</dd></div><div><dt>Link de origem fictício</dt><dd>${esc(offer.sourceUrl)}</dd></div></dl></div>
  ${offer.condition==='unknown'||manual?`<section class="classification"><h2>${manual?'Corrigir sua classificação':'Você conseguiu confirmar o funcionamento?'}</h2><p>A escolha gravada é preservada nas próximas coletas. Classificar ou corrigir não dispara WhatsApp.</p>${state.errorForm==='classification'?errorSummary('classification-error',{},state.saveMessage):''}<div class="row">${action('good')}${action('defect')}</div>${state.pending==='classification'?'<p role="status" class="saving-copy">Salvando classificação…</p>':''}</section>`:''}
  <section class="comparables"><div class="section-heading"><h2>Referências de usados</h2><span>${refs.length} exibidas no exemplo</span></div><p class="muted small">Preços anunciados não comprovam vendas. Referências, equivalência e método são fictícios.</p>${refs.length?`<div class="reference-list">${refs.map(ref=>`<div class="reference-row"><span><a class="text-link" href="?view=reference&offer=${offer.id}&ref=${ref.id}" data-reference="${ref.id}">${esc(ref.title)}</a><small>${esc(ref.origin)} · ${esc(ref.id)}</small><small>Observado no exemplo em ${ref.observedAt}</small></span><b>${money(ref.price)}</b></div>`).join('')}</div>`:notice({title:'Referências insuficientes no exemplo',text:'Não foi estimado preço de revenda nem lucro. A oferta continua visível.',kind:'warning'})}</section><section class="new-reference"><h2>Referência de produto novo</h2><div class="reference-row"><span>Separada da estimativa de usado</span><b>${money(offer.newReference)}</b></div></section></div>
  <aside class="valuation-panel"><div class="panel-price"><span>Preço de compra</span><strong>${money(offer.price)}</strong>${offer.previous?`<small>Antes: <s>${money(offer.previous)}</s></small>`:''}</div><h2>Como chegamos ao lucro</h2>${profit===null?notice({title:'Estimativa indisponível',text:'Faltam dados de compra, modalidade ou revenda. Isso não significa lucro zero.',kind:'warning'}):''}<dl class="cost-breakdown"><div><dt>Revenda estimada de usado</dt><dd>${money(offer.resale)}</dd></div><div><dt>Preço de compra</dt><dd>${money(offer.price)}</dd></div><div><dt>Taxa provisória<span>${state.settings.rate}% · estimada</span></dt><dd>${money(fee)}</dd></div><div><dt>${offer.delivery==='pickup'?'Frete · não se aplica':offer.delivery==='unknown'?'Frete · modalidade não confirmada':offer.freight===null?'Frete estimado configurado':'Frete informado no exemplo'}</dt><dd>${money(freight)}</dd></div></dl>${profit===null?'':`<div class="profit-total ${profit<0?'is-negative':''}"><span>Lucro estimado</span><strong>${profit<0?'−':'+'} ${money(Math.abs(profit))}</strong></div>`}<p class="valuation-note">Estimativa demonstrativa, sem garantia de retorno. Outros custos podem alterar o resultado.</p>${button({label:'Ver anúncio original',iconName:'external',attributes:'data-action="original"'})}<p class="panel-footnote">Negociação, compra e revenda acontecem fora do Garimpei.</p>${state.original?notice({title:'Anúncio de demonstração',text:`Identificação ${offer.sourceId}. O link exibido é fictício; nenhuma plataforma foi integrada.`,kind:'info'}):''}</aside></div>`;
}

export function referenceView(state) {
  const refs=state.offers.flatMap(offer=>comparablesFor(offer));
  const ref=refs.find(item=>item.id===state.reference);
  return titleBlock(ref?'Referência de usado':'Referência não encontrada','Detalhes fictícios para revisar a identificação dos anúncios comparados.')+(ref?`<section class="form-section reference-detail"><h2>${esc(ref.title)}</h2><dl class="source-details"><div><dt>Preço anunciado</dt><dd>${money(ref.price)}</dd></div><div><dt>Origem</dt><dd>${esc(ref.origin)}</dd></div><div><dt>ID do anúncio</dt><dd>${esc(ref.id)}</dd></div><div><dt>Observado em</dt><dd>${ref.observedAt}</dd></div><div><dt>URL fictícia</dt><dd>${esc(ref.url)}</dd></div></dl>${notice({title:'Referência de demonstração',text:'Esta referência identifica um anúncio fictício. Fontes e critérios reais dependem do discovery.',kind:'info'})}</section>`:'')+button({label:'Voltar aos detalhes',variant:'secondary',attributes:'data-action="back-detail"'});
}

const categoriesField=(selected,name='category')=>`<fieldset class="category-fieldset" id="interests" tabindex="-1"><legend>Selecione categorias de exemplo</legend><div class="category-options">${categories.map(category=>`<label class="category-option"><input type="checkbox" name="${name}" value="${esc(category)}" ${selected.includes(category)?'checked':''}><span>${esc(category)}</span>${icon('check')}</label>`).join('')}</div></fieldset>`;
const errorsFor=(state,form)=>state.errorForm===form?state.errors:{};
const saveError=(state,form)=>state.errorForm===form?errorSummary(`${form}-error`,state.errors,state.saveMessage):'';
const productList=(products,setup=false)=>`<ul class="product-list">${products.map((product,index)=>`<li><span>${icon('search')}${esc(product)}</span><button type="button" class="icon-button" data-${setup?'setup-remove':'remove-product'}="${index}" aria-label="Remover ${esc(product)}">${icon('close')}</button></li>`).join('')}</ul>`;

export function interestsView(state) {
  const errors=errorsFor(state,'product');
  return titleBlock('Seu garimpo tem direção.','Escolha categorias e cadastre produtos pelo nome ou modelo.')+`<div class="settings-layout"><div class="stack"><section class="form-section"><h2>Produtos que você procura</h2><p>Nome ou modelo é suficiente. As categorias são fictícias e não escolhem uma plataforma.</p><form id="product-form" novalidate>${saveError(state,'product')}<fieldset class="form-fields" ${state.pending?'disabled':''}><div class="add-product">${field({id:'product-name',label:'Nome ou modelo',value:state.productDraft,help:'Ex.: Sony a6000. Não exige armazenamento ou geração.',error:errors['product-name']})}${button({label:'Adicionar produto',loading:state.pending==='product',attributes:'type="submit"'})}</div></fieldset></form>${productList(state.products)}</section><section class="form-section"><h2>Também quero explorar categorias</h2><p>As categorias reais dependem da plataforma escolhida.</p><form id="categories-form">${saveError(state,'categories')}<fieldset class="form-fields" ${state.pending?'disabled':''}>${categoriesField(state.categoryDraft)}${button({label:'Salvar categorias',loading:state.pending==='categories',attributes:'type="submit"'})}</fieldset></form></section></div><aside class="helper-panel">${icon('compass')}<h2>Comece pelo que você conhece.</h2><p>A coleta e os alertas usam seus interesses configurados. Neste laboratório, todas as alterações ficam apenas em memória.</p><a class="text-link" href="?view=offers" data-nav="offers">Explorar ofertas ${icon('arrow')}</a></aside></div>`;
}

export function settingsView(state) {
  const errors=errorsFor(state,'settings'),draft=state.settingsDraft;
  return titleBlock('Os custos também fazem parte.','Configure sua região e os valores usados nas estimativas.')+`<div class="settings-layout"><form id="settings-form" class="stack" novalidate>${saveError(state,'settings')}<fieldset class="form-fields stack" ${state.pending?'disabled':''}><section class="form-section"><h2>Onde você compra</h2><p>Retirada em São Paulo, até 20 km do CEP configurado, e envio nacional quando houver entrega.</p>${field({id:'cep',label:'CEP de referência',value:draft.cep,inputmode:'numeric',autocomplete:'postal-code',help:'A validação de formato não confirma localização ou entrega.',error:errors.cep})}</section><section class="form-section"><h2>Custos estimados</h2><p>Este cenário representa uma configuração já preenchida. No primeiro uso, os custos começam em branco.</p><div class="two-fields">${costFields(draft,errors)}</div></section><div class="form-actions">${button({label:'Salvar configurações',loading:state.pending==='settings',attributes:'type="submit"'})}<span class="muted small">Os dados duram até recarregar a página.</span></div></fieldset></form><aside class="helper-panel"><h2>Uma conta transparente.</h2><div class="formula"><span>Revenda estimada</span><span>− Compra</span><span>− Custos estimados</span><strong>= Lucro estimado</strong></div><p>Ao salvar, os custos são recalculados nas ofertas de demonstração.</p></aside></div>`;
}
function costFields(draft,errors={}) {
  return field({id:'shipping',label:'Frete estimado (R$)',value:draft.shipping,inputmode:'decimal',help:'Usado apenas quando a fonte não informar frete.',error:errors.shipping})+field({id:'rate',label:'Taxa provisória de revenda (%)',value:draft.rate,inputmode:'decimal',help:'Percentual estimado sobre a revenda; não é uma tarifa confirmada.',error:errors.rate});
}

export function setupView(state) {
  const {step,draft}=state.setup,errors=errorsFor(state,'setup');
  const stepNames=['Sua região','Custos','Interesses'];
  let form;
  if(step===1)form=`<h2>Onde você quer garimpar?</h2><p>Seu CEP ajuda a contextualizar retirada em São Paulo e ofertas com envio.</p>${field({id:'cep',label:'CEP de referência',value:draft.cep,inputmode:'numeric',autocomplete:'postal-code',help:'Formato 00000-000. A demonstração não consulta localização nem entrega.',error:errors.cep})}`;
  if(step===2)form=`<h2>Uma estimativa com os seus custos.</h2><p>Preencha os dois valores para continuar. Você poderá ajustá-los depois.</p><div class="two-fields">${costFields(draft,errors)}</div>`;
  if(step===3)form=`<h2>O que você quer acompanhar?</h2><p>Selecione categorias ou adicione produtos por nome/modelo. Os exemplos abaixo não definem a plataforma de origem.</p>${field({id:'setup-product',label:'Nome ou modelo',value:draft.product,help:'Nome/modelo é suficiente. Use Adicionar produto antes de concluir.'})}<div class="setup-add">${button({label:'Adicionar produto',variant:'secondary',iconName:'plus',attributes:'type="button" data-action="setup-add-product"'})}</div>${productList(draft.products,true)}${categoriesField(draft.categories,'setup-category')}${errors.interests?`<p id="interests-error" class="field-error" tabindex="-1">${esc(errors.interests)}</p>`:''}`;
  return titleBlock('Prepare seu primeiro garimpo.','Uma configuração curta para começar com sua região, seus custos e seus interesses.')+`<div class="setup-layout"><section class="setup-panel"><ol class="setup-steps" aria-label="Etapas da configuração">${stepNames.map((name,index)=>`<li ${step===index+1?'aria-current="step"':''}><span>${index+1}</span>${name}${index+1<step?icon('check'):''}</li>`).join('')}</ol><form id="setup-form" novalidate>${saveError(state,'setup')}<fieldset class="form-fields" ${state.pending?'disabled':''}>${form}<div class="setup-actions">${step>1?button({label:'Voltar',variant:'secondary',attributes:'type="button" data-action="setup-back"'}):'<span></span>'}${button({label:step===3?'Concluir e começar':'Continuar',loading:state.pending==='setup',attributes:'type="submit"'})}</div></fieldset></form></section><aside class="helper-panel">${icon('compass')}<h2>Primeiro, conhecer as ofertas.</h2><p>Ao concluir, a primeira coleta organiza os anúncios sem enviar alertas pelo WhatsApp. Nos próximos usos, o acompanhamento retoma a configuração salva.</p><p class="small">Neste protótipo, salvar e reiniciar são simulações em memória. Recarregar a página restaura a demonstração.</p></aside></div>`;
}

export function alertsView(state) {
  const items=alertExamples.filter(item=>state.alerts.includes(item.id));
  const active=items.find(item=>item.id===state.message);
  const original=active?initialOffers.find(offer=>offer.id===active.offer):null;
  const preview=active?`<div class="message-bubble"><strong>Garimpei · ${esc(active.tag)}</strong><img src="assets/${original.image}" alt="Imagem ilustrativa" width="400" height="240"><h3>${esc(original.title)}</h3><p>Compra: ${money(original.price)}<br>Revenda estimada: ${money(original.resale)}<br>Lucro estimado: ${money(profitOf(original,initialSettings.rate,initialSettings.shipping*100))}</p><p>Valores do evento de demonstração, anteriores a alterações posteriores de custos.</p><span>Link de origem fictício · demonstração</span></div>`:'<div class="message-placeholder"><h2>Uma oferta, todos os detalhes.</h2><p>Selecione “Ver mensagem” para conferir o conteúdo proposto.</p></div>';
  return titleBlock('O que chegou até você.','Exemplos de mensagens e estados de confirmação, sem envio real.')+notice({title:'Prévia do comportamento',text:'O histórico é fictício. Classificar ou corrigir uma oferta não gera mensagem.',kind:'info'})+(items.length?`<div class="alerts-layout"><section class="alert-history"><div class="section-heading"><h2>Histórico de demonstração</h2></div>${items.map(item=>`<article class="alert-row"><span class="alert-icon">${icon(item.kind==='confirmed'?'check':'info')}</span><div><div class="row">${badge(item.kind==='confirmed'?'Envio confirmado no exemplo':'Confirmação incerta',item.kind==='confirmed'?'positive':'warning')}<time>${item.time}</time></div><h3>${esc(item.title)}</h3><p>${esc(item.body)}</p><div class="row"><button class="text-link inline-button" data-message="${item.id}">Ver mensagem</button><a class="text-link" href="?offer=${item.offer}" data-offer="${item.offer}">Conferir oferta ${icon('right')}</a></div></div></article>`).join('')}</section><aside class="message-panel"><h2 class="message-heading">${icon('bell')} Prévia de mensagem</h2>${preview}<p class="muted small">Sessão, destinatário e tentativas permanecem para especificação. O exemplo não oferece reenvio.</p></aside></div>`:emptyState({title:'Nenhum alerta enviado',text:'A configuração e a primeira coleta são silenciosas. Classificações manuais também não geram mensagens.'}));
}

export function prototypeControls(state) {
  return `<div class="prototype-bar" role="region" aria-label="Controles do protótipo"><span class="prototype-bar-label">Estudo de interface</span><button class="icon-button" data-variant-delta="-1" aria-label="Variação anterior">${icon('left')}</button><span class="variant-label"><strong>${variantNames[state.variant]}</strong><small>${variants.indexOf(state.variant)+1} de 3</small></span><button class="icon-button" data-variant-delta="1" aria-label="Próxima variação">${icon('right')}</button><span class="prototype-separator"></span><label class="scenario-label"><span class="sr-only">Cenário demonstrativo</span><select id="scenario">${Object.entries(scenarios).map(([key,label])=>`<option value="${key}" ${state.scenario===key?'selected':''}>${label}</option>`).join('')}</select></label><details class="prototype-inspector"><summary aria-label="Ferramentas e estado da demonstração">${icon('sliders')}</summary><div><strong>Ferramentas da demonstração</strong><p>Todos os efeitos ficam em memória.</p><div class="stack demo-tools"><label><input type="checkbox" id="write-error" ${state.writeError?'checked':''}> Simular falha de gravação</label>${button({label:'Simular novos dados',variant:'secondary',attributes:'data-action="queue-updates"'})}${button({label:'Simular reinício',variant:'secondary',attributes:'data-action="restart"'})}${button({label:'Concluir coleta simulada',variant:'secondary',attributes:'data-action="finish-initial"'})}</div><pre id="prototype-state"></pre></div></details></div>`;
}
